const msg = $json.message || {};
const text = String(msg.text || '').trim();
const chat_id = msg.chat?.id;
if (!text || chat_id === undefined) return [];
if (/^\/(start|help)$/i.test(text)) return [{json:{help:true,chat_id}}];
let mode = 'singer', query = text;
const m = text.match(/^\/(歌手|singer|歌曲|song)\s+(.+)$/i) || text.match(/^(歌手|歌曲|singer|song)\s*[:：]\s*(.+)$/i);
if (m) { mode = /歌曲|song/i.test(m[1]) ? 'song' : 'singer'; query = m[2].trim(); }
return [{json:{mode,query,chat_id:String(chat_id),callback_url:($env.N8N_PUBLIC_URL || '') + '/webhook/qqmusic-callback',callback_token:$env.CALLBACK_TOKEN || ''}}];

